SELECT (SELECT id FROM quests WHERE code = 'MONTANAS_SEC_CABRA_REINA'), i.id, v.qty FROM (VALUES ('POCION_DE_VIDA_MAYOR', 2)) AS v(code, qty) JOIN items i ON i.code = v.code;
